ULES') { return ['success' => false, 'message' => 'Action payload bukan REVOKE atau REVOKE_MODULES.']; } if ($revocationData['license_id'] !== $currentLicense['license_id']) { return ['success' => false, 'message' => 'Revocation token tidak cocok dengan License ID aktif.']; } $currentInstallationId = InstallationService::getInstallationId(); if (isset($revocationData['installation_id']) && $revocationData['installation_id'] !== '*' && $revocationData['installation_id'] !== $currentInstallationId) { return ['success' => false, 'message' => 'Revocation token ditujukan untuk Installation ID berbeda.']; } $expectedRevokeAuthToken = LicenseVerifier::generateAuthToken((string) $revocationData['license_id'], (string) ($revocationData['installation_id'] ?? $currentInstallationId), 'REVOKE' ); if ( ! isset($revocationData['auth_token']) || ! hash_equals($expectedRevokeAuthToken, (string) $revocationData['auth_token'])) { Log::warning('[AUDIT] EVENT: DEACTIVATION_INVALID_AUTH_TOKEN', [ 'installation_id' => $currentInstallationId, 'license_id' => $currentLicense['license_id'], ]); return ['success' => false, 'message' => 'Encrypted Authority Token (auth_token) pada Revocation Token tidak valid.']; } $signature = $revocationData['signature']; $clean = $revocationData; unset($clean['signature']); ksort($clean); if (isset($clean['revoked_modules']) && is_array($clean['revoked_modules'])) { sort($clean['revoked_modules']); } if (isset($clean['modules']) && is_array($clean['modules'])) { sort($clean['modules']); } $canonical = json_encode($clean, JSON_UNESCAPED_SLASHES); if ( ! LicenseVerifier::verifyAsymmetricSignature($canonical, $signature)) { Log::warning('[AUDIT] EVENT: DEACTIVATION_UNAUTHORIZED', [ 'installation_id' => $currentInstallationId, 'license_id' => $currentLicense['license_id'], ]); return ['success' => false, 'message' => 'Tanda tangan digital Revocation Token tidak sah (Ditolak oleh Public Key).']; } $revokedModules = $revocationData['revoked_modules'] ?? $revocat